    final KZG kzg, final DataColumnSidecar dataColumnSidecar) {

  final List<KZGCellWithColumnId> cellWithIds =
      IntStream.range(0, dataColumnSidecar.getDataColumn().size())
          .mapToObj(
              rowIndex ->
